def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    bg = background(g)
    # find wall: full edge line of a single non-background colour
    sides = {
        'top': g[0, :], 'bottom': g[H-1, :], 'left': g[:, 0], 'right': g[:, W-1]
    }
    wall = None
    for name, line in sides.items():
        if len(set(line.tolist())) == 1 and line[0] != bg:
            wall = name
            break
    wc = int(sides[wall][0])
    if wall in ('top', 'bottom'):
        n, depth = W, H
    else:
        n, depth = H, W

    def pos(i, k):  # k = distance from wall (0 = wall)
        if wall == 'top': return (k, i)
        if wall == 'bottom': return (H-1-k, i)
        if wall == 'left': return (i, k)
        return (i, W-1-k)

    bars = []
    for i in range(n):
        L = 0
        while 1 + L < depth and g[pos(i, 1 + L)] != bg and g[pos(i, 1 + L)] != wc:
            L += 1
        if L:
            bars.append((i, L, int(g[pos(i, 1)])))

    # Stage 1: length-2 bars vanish and become wall-coloured blocks at the far edge
    for i, L, c in bars:
        if L == 2:
            for k in (1, 2):
                g[pos(i, k)] = bg
            for k in (depth-1, depth-2):
                g[pos(i, k)] = wc
    emit(g, "Each two-cell bar is removed and a two-cell wall-coloured block appears at the opposite edge in its line.")

    # Stage 2: single-cell bars grow to length 2
    for i, L, c in bars:
        if L == 1:
            g[pos(i, 2)] = c
    emit(g, "Each one-cell bar is extended to two cells away from the wall.")
    return g
